const ctxItems = $items('Video Gate');
const ctx = ctxItems.length ? ctxItems[0].json : {};

const taskId = $json?.data?.task_id;

if (!taskId) {
  return [{
    json: {
      chat_id: ctx.chat_id,
      task_reply:
`❌ لم يتم إنشاء المهمة في MoneyPrinterTurbo.

الاستجابة:
${JSON.stringify($json)}`
    }
  }];
}

const store = $getWorkflowStaticData('global');

if (!store.jobs) {
  store.jobs = [];
}

const job = {
  telegram_id: String(ctx.telegram_id),
  chat_id: ctx.chat_id,
  task_id: taskId,
  topic: ctx.video_subject,
  status: 'submitted',
  progress: 0,
  created_at: new Date().toISOString()
};

store.jobs.unshift(job);

// نحتفظ بآخر 100 مهمة فقط
store.jobs = store.jobs.slice(0,100);

return [{
  json: {
    ...ctx,
    task_id: taskId,
    task_reply:
`✅ تم إنشاء مهمة الفيديو

🎬 الموضوع:
${ctx.video_subject}

🆔 Task ID:
${taskId}

يمكنك استخدام /status لمتابعة الحالة.`
  }
}];

const ctxItems = $items('Status Gate');

if (!ctxItems.length) {
  throw new Error('STATUS_CONTEXT_NOT_FOUND');
}

const ctx = ctxItems[0].json;

const payload = $json?.data;

if (!payload) {
  throw new Error(
    'INVALID_STATUS_RESPONSE: ' +
    JSON.stringify($json)
  );
}

const store = $getWorkflowStaticData('global');

if (!store.jobs) {
  store.jobs = [];
}

const index = store.jobs.findIndex(
  j =>
    String(j.telegram_id) === String(ctx.telegram_id) &&
    j.task_id === ctx.task_id
);

let status = 'processing';

if (
  payload.state === -1 ||
  payload.failed_stage ||
  payload.error
) {
  status = 'failed';
} else if (
  Number(payload.progress || 0) >= 100
) {
  status = 'completed';
}

if (index >= 0) {
  store.jobs[index] = {
    ...store.jobs[index],
    status,
    state: payload.state,
    progress: Number(payload.progress || 0),
    failed_stage: payload.failed_stage ?? null,
    error: payload.error ?? null,
    videos: payload.videos ?? null,
    combined_videos: payload.combined_videos ?? null,
    audio_file: payload.audio_file ?? null,
    updated_at: new Date().toISOString()
  };
}

let message =
`📊 حالة الفيديو

🎬 الموضوع:
${index >= 0 ? store.jobs[index].topic : ''}

🆔 Task ID:
${ctx.task_id}

📈 التقدم:
${payload.progress ?? 0}%

⚙️ الحالة:
${status}`;

if (payload.failed_stage) {
  message += `

❌ مرحلة الفشل:
${payload.failed_stage}`;
}

if (payload.error) {
  message += `

⚠️ الخطأ:
${payload.error}`;
}

if (status === 'completed') {
  message += `

✅ الفيديو مكتمل`;
}

return [{
  json:{
    chat_id:ctx.chat_id,
    telegram_id:ctx.telegram_id,
    task_id:ctx.task_id,
    real_status:status,
    progress:Number(payload.progress || 0),
    state:payload.state,
    status_reply:message
  }
}];

const topic = String(
  $json.video_subject || ''
).trim();

if (!topic) {
  throw new Error('VIDEO_TOPIC_EMPTY');
}

const script =
`اليوم سنتحدث باختصار عن ${topic}.
سنقدم الفكرة بطريقة سهلة وواضحة تساعدك على فهم أهم النقاط المتعلقة بهذا الموضوع.
من المهم النظر إلى ${topic} بصورة عملية، والتركيز على المعلومات الأساسية بدل التفاصيل المعقدة.
خلال هذا الفيديو سنأخذ نظرة سريعة ومباشرة تساعدك على تكوين فكرة أفضل عن الموضوع.
إذا وجدت هذه المعلومات مفيدة، يمكنك الاحتفاظ بالفيديو والعودة إليه لاحقاً.
والآن دعنا نبدأ مع ${topic}.`;

return [{
  json:{
    ...$json,
    video_script:script
  }
}];

const store=$getWorkflowStaticData('global');

const jobs=
  Array.isArray(store.jobs)
    ? store.jobs
    : [];

const now=Date.now();

const selected=jobs
  .filter(j => {

    if (!j.task_id) {
      return false;
    }

    if (
      j.status === 'submitted' ||
      j.status === 'processing' ||
      !j.status
    ) {
      return true;
    }

    if (
      j.status === 'completed' &&
      !j.completion_detected_sent
    ) {
      const created=
        Date.parse(j.created_at || '');

      const age=
        Number.isFinite(created)
          ? now-created
          : Infinity;

      return age <= 30*60*1000;
    }

    return false;
  })
  .slice(0,20);

return selected.map(j => ({
  json:{
    task_id:j.task_id,
    chat_id:j.chat_id,
    telegram_id:j.telegram_id,
    video_subject:j.topic,
    created_at:j.created_at
  }
}));

const responses=$input.all();
const contexts=$items('Load Pending Jobs');

const store=$getWorkflowStaticData('global');

if (!Array.isArray(store.jobs)) {
  store.jobs=[];
}

const out=[];

for (let i=0; i<responses.length; i++) {

  const ctx=contexts[i]?.json;
  const payload=responses[i]?.json?.data;

  if (!ctx || !payload) {
    continue;
  }

  const progress=Number(payload.progress || 0);

  let status='processing';

  if (
    payload.state === -1 ||
    payload.failed_stage ||
    payload.error
  ) {
    status='failed';
  }

  const hasVideos =
    (
      Array.isArray(payload.videos) &&
      payload.videos.length > 0
    ) ||
    (
      Array.isArray(payload.combined_videos) &&
      payload.combined_videos.length > 0
    );

  if (
    progress >= 100 ||
    hasVideos
  ) {
    status='completed';
  }

  const index=store.jobs.findIndex(
    j => j.task_id === ctx.task_id
  );

  if (index < 0) {
    continue;
  }

  const firstNotice=
    !store.jobs[index].auto_poll_notice_sent;

  store.jobs[index]={
    ...store.jobs[index],
    status,
    progress,
    state:payload.state,
    failed_stage:payload.failed_stage ?? null,
    error:payload.error ?? null,
    videos:payload.videos ?? null,
    combined_videos:payload.combined_videos ?? null,
    auto_poll_notice_sent:true,
    last_polled_at:new Date().toISOString()
  };

  out.push({
    json:{
      ...ctx,
      status,
      progress,
      state:payload.state,
      send_notice:firstNotice,
      poll_notice:
`🔄 المتابعة التلقائية تعمل

🆔 ${ctx.task_id}

📈 الحالة الحقيقية من Editing-Pingoo:
${progress}%`
    }
  });
}

return out;

const store=$getWorkflowStaticData('global');

if (!Array.isArray(store.jobs)) {
  store.jobs=[];
}

const output=[];

for (const item of $input.all()) {

  const data=item.json;

  if (data.status !== 'completed') {
    continue;
  }

  const index=
    store.jobs.findIndex(
      j => j.task_id === data.task_id
    );

  if (index < 0) {
    continue;
  }

  if (
    store.jobs[index].completion_detected_sent
  ) {
    continue;
  }

  store.jobs[index]={
    ...store.jobs[index],
    completion_detected_sent:true,
    completion_detected_at:
      new Date().toISOString()
  };

  output.push({
    json:{
      ...data,

      completion_notice:
`✅ تم اكتشاف اكتمال الفيديو تلقائياً

🎬 الموضوع:
${data.video_subject || ''}

🆔 Task ID:
${data.task_id}

📈 التقدم:
${data.progress}%

⚙️ الحالة:
completed`
    }
  });
}

return output;
